package com.gwynejsn.kite.security.web;import com.gwynejsn.kite.security.application.AuthService;import com.gwynejsn.kite.security.application.dto.*;import lombok.extern.slf4j.Slf4j;import org.springframework.http.HttpStatus;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.PostMapping;import org.springframework.web.bind.annotation.RequestBody;import org.springframework.web.bind.annotation.RequestMapping;import org.springframework.web.bind.annotation.RestController;@RestController@RequestMapping("/auth")@Slf4jpublic class AuthController {    private final AuthService authService;    public AuthController(AuthService authService) {        this.authService = authService;    }    @PostMapping("/login")    public ResponseEntity<LoginUserResponse> login(@RequestBody LoginUserRequest loginUserRequest) {        log.info("Login user request: {}", loginUserRequest);        return ResponseEntity.ok(authService.loginUser(loginUserRequest));    }    @PostMapping("/sign-up")    public ResponseEntity<String> signUp(@RequestBody CreateUserRequest user) {        return ResponseEntity                .status(HttpStatus.CREATED)                .body(authService.signUpUser(user));    }    @PostMapping("/logout")    public ResponseEntity<Void> logout(@RequestBody LogoutRequest refreshToken) {        authService.logoutUser(refreshToken.refreshToken());        return ResponseEntity.noContent().build();    }    @PostMapping("/refresh")    public ResponseEntity<RefreshTokenResponse> refreshToken(@RequestBody RefreshTokenRequest refreshTokenRequest) {        return ResponseEntity.ok(authService.refreshToken(refreshTokenRequest.refreshToken()));    }}